# ============================================================
# Voegt Italiaans (IT) toe aan partner-dashboard.html als 3e taal.
# - Voegt een 'it: {...}' blok toe aan het T vertaal-object (235 teksten)
# - Verruimt de taal-clamp in setLang() naar sq/en/it
# - Voegt een IT-optie toe aan de taal-dropdown
# - Werkt 3 losse hardgecodeerde EN/SQ tekstjes bij naar 3-weg (promocode + welkomstbonus)
# Zoekt alle plekken dynamisch op (telt accolades / exacte br-tekst), dus
# ongevoelig voor regeleindes of kleine opmaakverschillen.
# ============================================================

function DecodeHex($hex) {
    $bytes = New-Object byte[] ($hex.Length / 2)
    for ($i = 0; $i -lt $hex.Length; $i += 2) {
        $bytes[$i/2] = [Convert]::ToByte($hex.Substring($i,2),16)
    }
    return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function FindMatchingBrace($text, $openIdx) {
    $depth = 0
    for ($i = $openIdx; $i -lt $text.Length; $i++) {
        $ch = $text[$i]
        if ($ch -eq '{') { $depth++ }
        elseif ($ch -eq '}') {
            $depth--
            if ($depth -eq 0) { return $i }
        }
    }
    return -1
}

$ProjectPath = "C:\Savoraapp.com"
$PublicDir   = Join-Path $ProjectPath "public"
$target      = Join-Path $PublicDir "partner-dashboard.html"
$stamp       = Get-Date -Format "yyyyMMdd-HHmmss"

if (-not (Test-Path $target)) {
    Write-Host "FOUT: partner-dashboard.html niet gevonden op $target" -ForegroundColor Red
    exit 1
}

Copy-Item $target "$target.$stamp.bak" -Force
Write-Host "Backup gemaakt: partner-dashboard.html.$stamp.bak" -ForegroundColor DarkGray

$c = [System.IO.File]::ReadAllText($target, [System.Text.Encoding]::UTF8)
$origLen = $c.Length

# --- Stap 1: 'it' vertaalblok invoegen na het 'en' blok in het T object ---
$tIdx = $c.IndexOf("var T = {")
if ($tIdx -lt 0) { $tIdx = $c.IndexOf("var T=") }
if ($tIdx -lt 0) {
    Write-Host "FOUT: 'var T = {' niet gevonden. Niets gewijzigd." -ForegroundColor Red
    exit 1
}
$enIdx = $c.IndexOf("en:", $tIdx)
if ($enIdx -lt 0) {
    Write-Host "FOUT: 'en:' blok niet gevonden binnen T. Niets gewijzigd." -ForegroundColor Red
    exit 1
}
$enOpen = $c.IndexOf('{', $enIdx)
$enEnd = FindMatchingBrace $c $enOpen
if ($enEnd -lt 0) {
    Write-Host "FOUT: kon het 'en' blok niet volledig afbakenen. Niets gewijzigd." -ForegroundColor Red
    exit 1
}

$itBlock = DecodeHex ''
$insertPoint = $enEnd + 1
$c = $c.Substring(0, $insertPoint) + ",`n" + $itBlock + $c.Substring($insertPoint)

# --- Stap 2: taal-clamp verruimen (sq/en -> sq/en/it) ---
$oldClamp = "if (lang !== 'en') lang = 'sq';"
$newClamp = "if (lang !== 'en' && lang !== 'it') lang = 'sq';"
$clampCount = ([regex]::Matches($c, [regex]::Escape($oldClamp))).Count
if ($clampCount -eq 1) {
    $c = $c.Replace($oldClamp, $newClamp)
    Write-Host "Taal-clamp bijgewerkt (sq/en/it)." -ForegroundColor Green
} else {
    Write-Host "WAARSCHUWING: taal-clamp regel niet exact 1 keer gevonden (gevonden: $clampCount). Overgeslagen." -ForegroundColor Yellow
}

# --- Stap 3: IT-optie toevoegen aan de dropdown ---
$oldDropdown = "<div class=`"lang-option`" data-lang=`"en`" onclick=`"setLang('en')`"><img src=`"https://flagcdn.com/w40/gb.png`" alt=`"EN`"> English</div>"
$newDropdown = $oldDropdown + "`n    <div class=`"lang-option`" data-lang=`"it`" onclick=`"setLang('it')`"><img src=`"https://flagcdn.com/w40/it.png`" alt=`"IT`"> Italiano</div>"
$ddCount = ([regex]::Matches($c, [regex]::Escape($oldDropdown))).Count
if ($ddCount -eq 1) {
    $c = $c.Replace($oldDropdown, $newDropdown)
    Write-Host "IT-optie toegevoegd aan de taal-dropdown." -ForegroundColor Green
} else {
    Write-Host "WAARSCHUWING: dropdown-regel niet exact 1 keer gevonden (gevonden: $ddCount). Overgeslagen." -ForegroundColor Yellow
}

# --- Stap 4: 3 losse hardgecodeerde EN/SQ tekstjes -> 3-weg (promocode + welkomstbonus) ---
$promo1OldHex = ''
$promo1NewHex = ''
$oldPromo1 = DecodeHex $promo1OldHex
$newPromo1 = DecodeHex $promo1NewHex
if (([regex]::Matches($c, [regex]::Escape($oldPromo1))).Count -eq 1) { $c = $c.Replace($oldPromo1, $newPromo1) }

$promo2OldHex = '656c7365207b206d73672e7374796c652e636f6c6f72203d202723646332363236273b206d73672e74657874436f6e74656e74203d202863757272656e744c616e67203d3d3d2027656e27203f2027496e76616c696420636f646527203a20274b6f642069207061766c65667368c3ab6d27293b207d'
$promo2NewHex = ''
$oldPromo2 = DecodeHex $promo2OldHex
$newPromo2 = DecodeHex $promo2NewHex
if (([regex]::Matches($c, [regex]::Escape($oldPromo2))).Count -eq 1) { $c = $c.Replace($oldPromo2, $newPromo2) }

$wgOldHex = ''
$wgNewHex = ''
$wgOld = DecodeHex $wgOldHex
$wgNew = DecodeHex $wgNewHex
if (([regex]::Matches($c, [regex]::Escape($wgOld))).Count -eq 1) {
    $c = $c.Replace($wgOld, $wgNew)
    Write-Host "Welkomstbonus-tekst bijgewerkt (sq/en/it)." -ForegroundColor Green
} else {
    Write-Host "WAARSCHUWING: welkomstbonus-tekst niet exact 1 keer gevonden. Overgeslagen." -ForegroundColor Yellow
}

[System.IO.File]::WriteAllText($target, $c, (New-Object System.Text.UTF8Encoding($false)))

$check = [System.IO.File]::ReadAllText($target, [System.Text.Encoding]::UTF8)
$hasItBlock = $check.Contains("loginTitle: 'Accesso Partner'")
$hasClamp = $check.Contains("lang !== 'it'")
$hasDropdown = $check.Contains('data-lang="it"')
$nOpen = ([regex]::Matches($check, '\{')).Count
$nClose = ([regex]::Matches($check, '\}')).Count

Write-Host ""
Write-Host "Controle na wijziging:" -ForegroundColor Cyan
Write-Host "  Italiaans vertaalblok aanwezig (verwacht True): $hasItBlock"
Write-Host "  Taal-clamp bijgewerkt (verwacht True):          $hasClamp"
Write-Host "  IT-dropdown-optie aanwezig (verwacht True):     $hasDropdown"
Write-Host "  Accolades in balans (open=$nOpen, close=$nClose):"
Write-Host ""

if (-not $hasItBlock -or -not $hasClamp -or -not $hasDropdown -or ($nOpen -ne $nClose)) {
    Write-Host "WAARSCHUWING: een of meer controles niet gehaald. NIET deployen - herstel uit de backup en meld dit." -ForegroundColor Red
    exit 1
}

Write-Host "=== Deployen naar Cloudflare Pages ===" -ForegroundColor Cyan
Set-Location $ProjectPath
$wt = Join-Path $ProjectPath "wrangler.toml"
if (Test-Path $wt) { Rename-Item $wt "$wt.bak" -Force }
try {
    npx wrangler pages deploy public --project-name=savoraapp
} finally {
    if (Test-Path "$wt.bak") { Rename-Item "$wt.bak" $wt -Force }
}
Write-Host "Klaar. Test https://savoraapp.com/partner-dashboard.html (Ctrl+Shift+R) en kies IT in de taal-dropdown rechtsboven." -ForegroundColor Cyan